      scouts:[S(50,115,"Gateway / gas read","Is the opponent preserving Nexus options or compressing units/tech?","The first structure/gas read bounds the early threat.","It decides how much economy you can safely retain."),S(125,220,"Hidden-tech check","What expensive branch is absent from the visible army?","Robo, Stargate, Twilight, or concealed proxy changes the next fight.","Resolve this before taking a fragile expansion."),S(230,330,"Army + expansion renewal","Is the opponent adding economy or concentrating local power?","A third Nexus is only safe if the immediate local fight remains defensible.","More economy permits matching; concentrated units revoke greed." )],
